 if(test[0].equals("delay"))i.check("true".equals(TossHomeChecks.js(i,home,"groupHistory.some(x=>x.actual&&x.text.includes('가상 접수증')&&x.text.includes('16:38'))")),"durable virtual change receipt returned in same chat");
 if(test[0].equals("rail"))i.check("true".equals(TossHomeChecks.js(i,home,"groupHistory.some(x=>x.actual&&x.text.includes('15:51')&&x.text.includes('16:32'))")),"server rail choices displayed in chat");
 if(test[0].equals("research"))i.check("true".equals(TossHomeChecks.js(i,home,"groupHistory.some(x=>x.text.includes('확인한 출처')&&x.text.includes('https://'))")),"observed browser sources returned to group chat");
